fn record_candidate_fill(feature: &str, filled: u64, total: u64) {
    CANDIDATE_FEATURE_FILL_TOTAL
        .with_label_values(&[feature, "filled"])
        .inc_by(filled);
    CANDIDATE_FEATURE_FILL_TOTAL
        .with_label_values(&[feature, "missing"])
        .inc_by(total.saturating_sub(filled));
}

